--- a/Sources/Clinic/DeepLink.swift
+++ b/Sources/Clinic/DeepLink.swift
@@ -7,15 +7,28 @@ enum DeepLink {

     static let scheme = "clinic"

-    static func card(for id: String) -> URL {
-        URL(string: "\(scheme)://cards")!
+    static func card(for id: String) -> URL {
+        let path = "\(scheme)://cards/\(id)"
+
+        return URL(string: path)!
+    }
+
+    static func open(_ notification: [String: Any], with router: Router) {
+        guard let id = notification["petId"] as? String else {
+            return
+        }
+
+        router.open(card(for: id))
     }

     static func isCard(_ url: URL) -> Bool {
         url.scheme == scheme && url.host == "cards"
     }
 }
